def P(num,h,fig,tier,grant,inv,title,teaches,figs,status="Expired",**k):
    d=dict(num=num,hash=h,fig=fig,tier=tier,grant=grant,inv=inv,title=title,teaches=teaches,figs=figs,status=status); d.update(k); return d
INTRO = "<p>A home weather station is a rain gauge, a wind vane, something that reacts to humidity, a barometer and a way to measure wind speed. Add a lightning rod to protect the buildings. These patent drawings show each one, from a funnel gauge, a wooden-strip hygrometer and a vane you can make, through a portable barometer and lightning-rod fittings, to clockwork self-recording instruments. Use them with the forecasting and storm chapters of this guide.</p>"
UNPATENTED = ["Reading clouds and wind shifts, using a pine cone or a hair as a humidity indicator, and the sealed-jar water barometer are traditional and free to use."]
PATENTS = [
P("US764315","8b/fc/58/3ada910d3ff1fb/US764315.pdf","cd/ed/4b/86fd7b73b8870c/US764315-drawings-page-1.png","A","1904-07-05","Fred Thomas (Des Moines, Iowa)","Rain-gage",
  "A compact rain gauge with a large capacity, made to pack small and be easy to carry and set up. It shows the receiver-funnel-and-measuring-tube layout every rain gauge uses, which can be copied with a can, a funnel and a narrow jar.","Section through receiver, funnel and measuring tube"),
P("US277533","83/c0/c4/bed2c839a2c6b0/US277533.pdf","80/8d/9e/736b5320717c65/US277533-drawings-page-1.png","A","1883-05-15","George A. Ayers (Holyoke, Massachusetts)","Hygrometer",
  "A humidity gauge made from strips of wood (moisture-absorbing posts) fixed in a base. As they swell and shrink they push a connecting rod that turns a hand over a dial. Make one from thin cross-grain wood strips.","Fig. 1 side elevation (posts, rod, dial hand); Figs. 2&ndash;3 details"),
P("US215028","3e/e0/26/b0f0e192e2424e/US215028.pdf","4e/22/cc/f517f1e0b22cef/US215028-drawings-page-1.png","A","1879-05-06","Edward S. Turner (Chicago)","Improvement in weather-vanes",
  "A weather vane whose tail is a light frame filled with glass. It shows the basic vane: a large tail and a pointing head balanced on a vertical spindle, with fixed N-E-S-W arms below.","Vane, frame tail and spindle"),
P("US18560","28/35/52/45f90efc4870a4/US18560.pdf","dd/83/01/886b6231352902/US18560-drawings-page-1.png","B","1857-11-03","Theodore R. Timby (Medina, New York)","Barometer",
  "A mercury barometer with a short rubber tube between the glass tube and its stop-cock. The rubber gives way when the mercury expands, so the glass does not burst when the barometer is laid down to be carried. Mercury is toxic: handle it only in trays and never heat it.","Figs. 1&ndash;2 elevations; Fig. 3 enlarged tube end with rubber section"),
P("US159961","f5/ee/5d/78ee1b77659693/US159961.pdf","bb/db/c9/249f793cf7e571/US159961-drawings-page-1.png","B","1875-02-16","Myron D. Phelps (Bristolville, Ohio)","Improvement in lightning-rods",
  "Lightning-rod construction and joints: how the rod sections and fittings are put together so there is one continuous conductor from the roof point down to the ground.","Rod sections, couplings and fastenings"),
P("US756109","2b/e0/a8/39c2e416f68c6e/US756109.pdf","95/ff/99/38a1f3e6deb07f/US756109-drawings-page-1.png","B","1904-03-29","Julien P. Friez (Baltimore, Maryland)","Rain gage",
  "A standard-pattern rain gauge with a stand, receiver, overflow cylinder and narrow measuring tube that magnifies the depth so small amounts of rain can be read. It is the layout a careful observer copies.","Section through stand, receiver, overflow cylinder and measuring tube"),
P("US245625","cb/c0/2d/be8dc0dd2ef477/US245625.pdf","16/f3/9e/cc2914df4a598b/US245625-drawings-page-1.png","C","1881-08-16","Henry J. Green (Brooklyn, New York)","Recording anemometer",
  "A self-recording cup anemometer: wind turns hemispherical cups on an upright shaft, and clockwork draws the wind run on a paper sheet. The cups alone, counted against a watch, give wind speed. The recorder needs instrument-making.","Cup wheel, shaft, clockwork and recording sheet"),
P("US530338","cc/63/71/f7f9e727d42900/US530338.pdf","04/6a/6a/91641c5fc2d895/US530338-drawings-page-1.png","C","1894-12-04","Alva J. Grover (Omaha, Nebraska)","Self-recording rain-gage",
  "A rain gauge that automatically records how much rain fell, when it began and how long it lasted, using a float and clockwork pen. It is a reference for building a recording gauge.","Sheet 1: gauge, float and recording mechanism"),
P("US168505","51/55/52/f3830006221e5e/US168505.pdf","a2/bd/a3/eda4f3d5406967/US168505-drawings-page-1.png","B","1875-10-05","William Klinkerfues (Director, Royal Observatory, G&ouml;ttingen)","Improvement in psychrometers",
  "A 'self-reducing' psychrometer that shows the saturation temperature (dew point) directly, so a lay observer need not work out absolute humidity from tables. Klinkerfues argues that humidity read alongside the barometer improves home weather forecasting, because the dew point tends to change some hours before the barometer does.","The face view of the instrument and its scales"),
P("US525273","aa/0a/64/e54c4f63901fbb/US525273.pdf","ea/87/b3/8de4edf2a82d6f/US525273-drawings-page-1.png","C","1894-08-28","David Logan","Aneroid barometer",
  "A storm alarm built onto an aneroid barometer. A pointer on the vacuum chamber trips an alarm when the air pressure falls to a level the observer sets with an adjustable screw, so it 'indicates audibly the approach of a storm'. The aneroid's sealed vacuum chamber is precision factory work; use a can or jar barometer as described in this guide for a home-made version.","Sheet 1: the vacuum chamber, adjusting pin and alarm trip"),
]
